-- INSERT preguntas PIR 2021 (convocatoria FSE 2021, Psicología)
-- Fuente: Cuaderno_2021_P_0_C.pdf + Plantilla_Respuestas_FSE_210_v2.xlsx
-- Generado: 202 preguntas validas de 210 impresas (8 anuladas excluidas: 59, 71, 80, 129, 134, 135, 151, 158)
-- especialidad/tema quedan NULL: se clasificaran en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2021) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2021 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

