INSERT INTO public.preguntas
  ("año", numero, especialidad, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2021, 1, NULL, '¿Qué mecanismos o sustancias visuales diferentes propuso Ewald Hering en su propuesta original de la teoría de los procesos oponentes para la percepción de los colores?:', 'Los mecanismos brillo, contraste e intensidad.', 'Los mecanismos de longitud y amplitud de onda.', 'Los mecanismos sinápticos excitatorios, inhibitorios y oponentes.', 'Los mecanismos blanco-negro, rojo-verde y amarillo-azul.', NULL, 'd', NULL, NULL),
  (2021, 2, NULL, '¿En qué consiste el problema de la Torre de Hanoi, utilizada en el campo de investigación de la resolución de problemas y la planificación?:', 'En tres pivotes con discos del mismo tamaño que deben apilarse para formar “torres” de la misma altura con algunas restricciones.', 'En tres pilas de discos de diferente tamaño que deben reorganizarse en “torres” que solo contengan discos del mismo tamaño con algunas restricciones.', 'En tres pivotes con discos de diferente tamaño que deben trasladarse del pivote inicial al pivote final con algunas restricciones.', 'En tres pivotes de discos del mismo tamaño que deben apilarse para formar “torres” de altura diferente con algunas restricciones.', NULL, 'c', NULL, NULL),
  (2021, 3, NULL, '¿Cuáles son los componentes del modelo triangular del amor de Sternberg (1988)?:', 'Sexualidad, apego y fidelidad.', 'Pasión, apego y compromiso.', 'Sexualidad, apego e intimidad.', 'Intimidad, pasión y compromiso.', NULL, 'd', NULL, NULL),
  (2021, 4, NULL, 'En un programa de reforzamiento positivo de intervalo fijo de cuatro minutos, ¿cuándo se le dispensa el reforzador al sujeto del experimento?:', 'La primera vez que el sujeto emita la respuesta operante después de haber transcurrido cuatro minutos desde que se dispensó el último reforzador.', 'Cada cuatro minutos con independencia de si el sujeto realiza la respuesta operante antes o después de transcurrido ese intervalo.', 'Cuatro minutos después de que el reforzador esté disponible.', 'Cuando el sujeto emite la respuesta operante tras cuatro minutos desde la presentación del estímulo discriminativo.', NULL, 'a', NULL, NULL),
  (2021, 5, NULL, 'En el campo de la psicología de la memoria, ¿en qué consiste el fenómeno del olvido inducido por la recuperación?:', 'La recuperación selectiva de recuerdos episódicos produce el olvido de otra información relacionada o asociada a las mismas claves de recuperación.', 'La recuperación repetida de información debilita la integridad original del trazo de memoria.', 'La dificultad de recordar una información en un momento concreto aumenta la probabilidad de olvido futuro de esa información.', 'La recuperación de información del pasado remoto induce el olvido de información reciente.', NULL, 'a', NULL, NULL),
  (2021, 6, NULL, '¿En qué consiste el procedimiento de devaluación del reforzador en el contexto del condicionamiento instrumental u operante?:', 'En disminuir progresivamente la cantidad de reforzador dispensado.', 'En reducir el número de respuestas operantes que se exigen para obtener el reforzador.', 'En aumentar la demora temporal entre la respuesta operante y la aparición del reforzador.', 'En asociar el reforzador con un estímulo o evento de naturaleza contraria.', NULL, 'd', NULL, NULL),
  (2021, 7, NULL, 'La falacia del razonamiento denominada “falacia del jugador”, la cual es cometida por muchos jugadores de casino, por la que piensan que el azar es un proceso que se corrige a sí mismo y que, además, conlleva la confusión en la utilización de la ley de los grandes números, es un error del pensamiento producido por:', 'El heurístico de accesibilidad.', 'El heurístico de anclaje y ajuste.', 'El heurístico de representatividad.', 'El heurístico del prototipo.', NULL, 'c', NULL, NULL),
  (2021, 8, NULL, 'El diencéfalo:', 'Está formado por los cuerpos celulares que rodean la sustancia gris periacueductal.', 'Tiene dos conjuntos de núcleos bilateralmente simétricos: los colículos superiores y los colículos inferiores.', 'Está conformado por el tálamo, hipotálamo, epitálamo y subtálamo.', 'Tiene como función principal el control de la respiración y el funcionamiento del sistema cardiovascular.', NULL, 'c', NULL, NULL),
  (2021, 9, NULL, '¿Cuál de las siguientes técnicas de registro de la actividad cerebral cuenta con peor resolución temporal?:', 'Electroencefalografía (EEG).', 'Magnetoencefalografía (MEG).', 'Registros intracraneales (iEEG).', 'Resonancia magnética funcional (RMf).', NULL, 'd', NULL, NULL),
  (2021, 10, NULL, 'El cromosoma 21, implicado en el síndrome de Down, se ha asociado también a:', 'La enfermedad de Alzheimer.', 'La enfermedad de Parkinson.', 'La enfermedad de Huntington.', 'El síndrome de Tourette.', NULL, 'a', NULL, NULL),
  (2021, 11, NULL, '¿Qué modalidad sensorial se procesa en el núcleo geniculado lateral del tálamo?:', 'Auditiva.', 'Visual.', 'Táctil.', 'Gustativa.', NULL, 'b', NULL, NULL),
  (2021, 12, NULL, 'En la sinapsis entre el sistema nervioso y la musculatura estriada o esquelética, el neurotransmisor más frecuente es la:', 'Dopamina.', 'Serotonina.', 'Acetilcolina.', 'Noradrenalina.', NULL, 'c', NULL, NULL),
  (2021, 13, NULL, '¿Cuál de estas áreas NO interviene en la inhibición de la conducta?:', 'Área premotora suplementaria.', 'Núcleo subtalámico.', 'Globo pálido interno.', 'Núcleo arqueado.', NULL, 'd', NULL, NULL),
  (2021, 14, NULL, 'Para la creación de imágenes virtuales de las vías de fibras nerviosas del cerebro, emplearíamos:', 'La tomografía computarizada.', 'La resonancia magnética con tensor de difusión.', 'La espectroscopia por resonancia magnética.', 'La estimulación magnética transcraneal.', NULL, 'b', NULL, NULL),
  (2021, 15, NULL, 'Respecto del sustrato neurológico de la memoria, señale la afirmación FALSA:', 'La corteza prefrontal izquierda participa más en la codificación de la información semántica que en su recuperación.', 'La corteza prefrontal izquierda participa más en la codificación de la información episódica que en su recuperación.', 'La corteza prefrontal derecha participa más en la recuperación de la memoria episódica que la corteza prefrontal izquierda.', 'La memoria semántica depende del sistema de memoria del lóbulo temporal medial-lóbulo prefrontal ventral.', NULL, 'd', NULL, NULL),
  (2021, 16, NULL, '¿Cuál de los siguientes trastornos NO se considera una tauopatía?:', 'Parálisis supranuclear progresiva.', 'Enfermedad de Alzheimer.', 'Trastorno frontotemporal.', 'Demencia por cuerpos de Lewy.', NULL, 'd', NULL, NULL),
  (2021, 17, NULL, '¿Cuál de las siguientes teorías NO está vinculada a la explicación del fenómeno de la facilitación social?:', 'Teoría de la aprehensión por la evaluación.', 'Teoría de la distracción-conflicto.', 'Teoría del impulso o de la motivación (o activación).', 'Teoría de la reactancia.', NULL, 'd', NULL, NULL),
  (2021, 18, NULL, '¿Qué proceso analiza la teoría de los estados de expectativas formulada por Berger y colaboradores?:', 'Las emociones generadas por las relaciones interpersonales.', 'La emergencia del estatus en las personas que integran los grupos.', 'El desarrollo de procesos de conformidad.', 'La aparición de conductas altruistas.', NULL, 'b', NULL, NULL),
  (2021, 19, NULL, '¿Cuál es la principal aportación que realiza la teoría de la conducta planificada a su predecesora, la teoría de la acción razonada?:', 'La supresión del componente “creencias conductuales”.', 'La introducción de relaciones no lineales entre constructos.', 'La introducción del componente “control conductual percibido”.', 'La incorporación de relaciones directas entre actitud y conducta.', NULL, 'c', NULL, NULL),
  (2021, 20, NULL, 'Según el modelo de contenido de los estereotipos propuesto por Fiske, la combinación de percepción de cordialidad/calidez baja y competencia alta de un exogrupo produce:', 'Compasión.', 'Admiración.', 'Envidia.', 'Desprecio.', NULL, 'c', NULL, NULL),
  (2021, 21, NULL, 'El modelo de disociación de Devine se centra en el conflicto que experimentan las personas “no prejuiciosas” (o “poco prejuiciosas”) entre sus respuestas automáticas de prejuicio y:', 'Su conducta real.', 'Sus propias emociones.', 'Los valores de su entorno social.', 'Sus creencias personales.', NULL, 'd', NULL, NULL),
  (2021, 22, NULL, 'El modelo experimental denominado paradigma del grupo mínimo está vinculado al surgimiento de la teoría denominada:', 'Teoría de la autoafirmación.', 'Teoría de la identidad social.', 'Teoría del pensamiento grupal.', 'Teoría de la dominancia social.', NULL, 'b', NULL, NULL),
  (2021, 23, NULL, 'Señale de qué reflejo se trata cuando un niño de menos de 3 meses se sobresalta cuando oye ruidos intensos o cuando se le suelta repentinamente a unos cuantos centímetros de la cama, extendiendo piernas, brazos y dedos, entre otras conductas:', 'Reflejo de Babinski.', 'Reflejo del primate.', 'Reflejo de Babkin.', 'Reflejo de Moro.', NULL, 'd', NULL, NULL),
  (2021, 24, NULL, 'Cuando los bebés se encuentran ante un objeto o situación nueva o ambigua, suelen mirar a sus cuidadores para obtener señales emocionales sobre cómo actuar. Este fenómeno se denomina:', 'Referenciación social.', 'Audiencia imaginaria.', 'Andamiaje.', 'Teoría de la mente.', NULL, 'a', NULL, NULL),
  (2021, 25, NULL, 'Ante la pregunta “¿Por qué no se puede robar en una tienda?”, una respuesta como “Porque te pueden pillar y te castigarían” es típica del siguiente nivel de desarrollo moral de Kohlberg:', 'Moralidad conformista.', 'Moralidad preconvencional.', 'Moralidad instrumental.', 'Moralidad heteronormativa.', NULL, 'b', NULL, NULL),
  (2021, 26, NULL, 'Cuando los niños dominan principios cognitivos como la reversibilidad, la descentración o la identidad, son capaces de resolver los siguientes problemas:', 'Problemas de adición y sustracción.', 'Problemas que implican coordinación cognitiva y emocional.', 'Problemas que van más allá de su zona de desarrollo próximo.', 'Problemas de conservación.', NULL, 'd', NULL, NULL),
  (2021, 27, NULL, 'El tipo de pensamiento adulto caracterizado por un abordaje de los problemas más flexible y dialéctico (integrando diferentes aspectos, incluso contradictorios, de la situación en un todo abarcativo), se denomina:', 'Pensamiento divergente.', 'Pensamiento pragmático.', 'Pensamiento integrativo.', 'Pensamiento posformal.', NULL, 'd', NULL, NULL),
  (2021, 28, NULL, 'De acuerdo con la perspectiva del ciclo vital (Baltes y Baltes, 1990), las tres estrategias o procesos básicos de adaptación que empleamos a lo largo del desarrollo son:', 'Selección, optimización y compensación.', 'Asimilación, acomodación y negación.', 'Integración, reestructuración y apertura a la experiencia.', 'Estrategias centradas en las emociones, en la cognición y en la acción.', NULL, 'a', NULL, NULL),
  (2021, 29, NULL, 'En un análisis de regresión simple, ¿cuál de los siguientes coeficientes indica el cambio que se produce en la variable de respuesta, por cada incremento en una unidad de la variable predictora?:', 'Coeficiente de regresión no estandarizado β1.', 'Coeficiente de regresión no estandarizado β0.', 'Coeficiente de regresión tipificado B1.', 'Coeficiente de determinación corregido.', NULL, 'a', NULL, NULL),
  (2021, 30, NULL, '¿Cuál de los siguientes estadísticos se emplea como indicador de multicolinealidad en los modelos de regresión lineal múltiple?:', 'Durbin-Watson.', 'Tolerancia.', 'Distancia de Cook.', 'Correlación de Pearson.', NULL, 'b', NULL, NULL),
  (2021, 31, NULL, 'Si en una regresión logística binaria tenemos un predictor categórico con cuatro niveles, ¿en cuántas variables dicotómicas (dummy) se transformaría para emplearlo en el modelo?:', 'En 2.', 'En 3.', 'En 4.', 'En 5.', NULL, 'b', NULL, NULL),
  (2021, 32, NULL, 'Cuando en el análisis de varianza unifactorial no se cumple el supuesto de homocedasticidad, en vez de la F ordinaria, ¿cuál de las siguientes pruebas convendría emplear?:', 'Brown-Forsythe.', 'Shapiro-Wilk.', 'Levene.', 'Mauchly.', NULL, 'a', NULL, NULL),
  (2021, 33, NULL, 'Si la respuesta de un sujeto a un ítem depende de su respuesta a otro u otros ítems del test, ¿qué supuesto de la teoría de respuesta al ítem se está incumpliendo?:', 'Invarianza respecto a los ítems.', 'Linealidad.', 'Igualdad de errores típicos.', 'Independencia local.', NULL, 'd', NULL, NULL),
  (2021, 34, NULL, '¿Cuál de los siguientes diseños de investigación es un diseño estructuralmente incompleto:', 'Diseño jerárquico.', 'Diseño de bloques aleatorios.', 'Diseño de covarianza.', 'Diseño con grupo de control no equivalente.', NULL, 'a', NULL, NULL),
  (2021, 35, NULL, 'Atendiendo a las propuestas estructurales de la personalidad, el punto de partida del modelo de Cattell fue:', 'El análisis de los aspectos biológicos.', 'El análisis del lenguaje.', 'El análisis del ambiente.', 'El análisis de la genética.', NULL, 'b', NULL, NULL),
  (2021, 36, NULL, 'Según el modelo de los cinco grandes factores (Costa y McCrae, 1992), la persona buscadora de emociones/excitaciones tiende a ser también:', 'Gregaria o sociable, activa y asertiva.', 'Impulsiva, sociable y desconfiada.', 'Competente, autodisciplinada y activa.', 'Cálida, impulsiva y activa.', NULL, 'a', NULL, NULL),
  (2021, 37, NULL, 'Entre las consecuencias o efectos posibles de la teoría de la reactancia (Brehm), NO se encuentra:', 'La restauración directa o ejecución de la conducta amenazada.', 'La restauración indirecta o por implicación.', 'La pérdida o disminución del atractivo de la conducta amenazada.', 'La negación de la amenaza.', NULL, 'c', NULL, NULL),
  (2021, 38, NULL, 'Respecto de la necesidad de logro, señale la alternativa correcta:', 'Las personas con un nivel bajo de necesidad de logro prefieren las tareas de dificultad moderada.', 'Las personas con un nivel alto de necesidad de logro prefieren las tareas muy difíciles de resolver.', 'Las personas con necesidad de logro alta prefieren tareas de dificultad media.', 'Las personas con necesidad de logro alta suelen elegir carreras universitarias de extrema dificultad.', NULL, 'c', NULL, NULL),
  (2021, 39, NULL, 'Desde el modelo atribucional de Weiner, ¿qué tres dimensiones se contemplan?:', 'Distintividad, consistencia y consenso.', 'Estabilidad, globalidad e internalidad.', 'Intencionalidad, estabilidad y especificidad.', 'Locus de causalidad, estabilidad y controlabilidad.', NULL, 'd', NULL, NULL),
  (2021, 40, NULL, 'Al aumento de la media en las puntuaciones de cociente intelectual (CI) a medida que se suceden las generaciones, se le denomina:', 'Efecto Catell.', 'Efecto Horn.', 'Efecto Flynn.', 'Efecto Stern.', NULL, 'c', NULL, NULL),
  (2021, 41, NULL, 'Señale qué capacidad/habilidad del modelo de inteligencia de Cattell-Horn-Carroll (CHC) evalúa, principalmente, el test de vocabulario del WISC-IV o WAIS-IV:', 'Inteligencia fluida.', 'Inteligencia cristalizada.', 'Almacenamiento y recuperación a largo plazo.', 'Memoria a corto plazo.', NULL, 'b', NULL, NULL),
  (2021, 42, NULL, '¿Cuál de los siguientes autores defiende una estructura de la inteligencia NO jerárquica?:', 'Catell.', 'Vernon.', 'Carroll.', 'Guilford.', NULL, 'd', NULL, NULL),
  (2021, 43, NULL, 'Respecto del programa de parentalidad (parenting) triple P positivo (Sanders) indique la respuesta FALSA:', 'El programa Triple P universal es un programa de prevención aplicado por profesionales de atención primaria.', 'El programa Triple P estándar se administra de forma grupal o individual por profesionales de la salud mental.', 'El programa Triple P selectiva consta de 1 o 2 sesiones para problemas leves de conducta.', 'El programa Triple P aumentado se orienta al comportamiento disruptivo que se ve complicado por estresores familiares añadidos.', NULL, 'a', NULL, NULL),
  (2021, 44, NULL, 'Respecto del programa de tratamiento No Worries! (Holmes, 2014) para el trastorno de ansiedad generalizada, señale la respuesta FALSA:', 'Es un tratamiento grupal tanto para niños como para padres.', 'Incluye el aprendizaje de estrategias de control de la ansiedad como respiración y relajación muscular.', 'Es un tratamiento principalmente de enfoque cognitivo que trabaja entre otros aspectos la intolerancia a la incertidumbre, las creencias negativas sobre la preocupación y la evitación cognitiva.', 'Es una adaptación del tratamiento metacognitivo de Wells para la ansiedad generalizada en población infanto-juvenil.', NULL, 'd', NULL, NULL),
  (2021, 45, NULL, 'El modelo de personalidad de Gray se caracteriza por:', 'Relacionar las dimensiones de impulsividad y ansiedad con una serie de mecanismos biológicos y con las recompensas y castigos que siguen a la conducta.', 'Combinar conceptos cognitivos y biológicos para describir el rendimiento cognitivo según las diferencias individuales en personalidad.', 'Analizar el nivel de activación cerebral en relación a los superfactores de psicoticismo, extraversión y neuroticismo.', 'Relacionar las diferencias individuales en extraversión con el rendimiento en determinadas tareas experimentales.', NULL, 'a', NULL, NULL),
  (2021, 46, NULL, 'Respecto de la técnica del diferencial semántico de Osgood y colaboradores, señale la opción FALSA:', 'Se sustenta en una teoría mediacional de corte neoconductista.', 'El significado denotativo hace referencia al contenido objetivo de un concepto.', 'El formato de respuesta más apropiado son las escalas de siete intervalos de respuesta.', 'Una de las instrucciones fundamentales a la hora de responder es que no se responda de manera rápida en función de la primera impresión.', NULL, 'd', NULL, NULL),
  (2021, 47, NULL, 'En la evaluación psicológica, ¿qué nivel de inferencia de la respuesta se apoya en el supuesto de relación o correlato por el cual lo evaluado pudiera asociarse con otras conductas?:', 'Nivel I.', 'Nivel II.', 'Nivel III.', 'Nivel IV.', NULL, 'b', NULL, NULL),
  (2021, 48, NULL, 'Entre los factores o rasgos establecidos por el modelo de la personalidad de Guilford, ¿cuál se considera un factor primario?:', 'Objetividad.', 'Disposición paranoide.', 'Extraversión.', 'Independencia.', NULL, 'a', NULL, NULL),
  (2021, 49, NULL, 'El aparato “Omega” es un instrumento de evaluación que se incluye dentro de las técnicas:', 'Perceptivas.', 'Cognitivas.', 'Motoras.', 'Estructurales.', NULL, 'c', NULL, NULL),
  (2021, 50, NULL, '¿Qué batería de inteligencia evalúa los procesos cognitivos con las siguientes subescalas: procesamiento simultáneo, procesamiento sucesivo y conocimientos?:', 'La Batería de evaluación para niños de Kaufman y Kaufman (K-ABC).', 'El Cognitive Assessment System (CAS) de Naglieri y Das.', 'La Escala de inteligencia Wechsler para preescolar y primaria (WPPSI-IV).', 'La Escala McCarhy de aptitudes y psicomotricidad (MSCA).', NULL, 'a', NULL, NULL),
  (2021, 51, NULL, 'Según la “Regla de las tres D” respecto de la observación directa, cuando segmentamos comportamientos observables en unidades precisas ¿cómo deben ser dichas unidades?:', 'Directas, definibles y determinadas.', 'Delimitables, denominables y definibles.', 'Divisibles, distinguibles y diferenciables.', 'Delimitables, denominables y determinadas.', NULL, 'b', NULL, NULL),
  (2021, 52, NULL, 'Señale la respuesta correcta con respecto a la entrevista motivacional:', 'Es una entrevista que comparte objetivos de evaluación e intervención al mismo tiempo.', 'Originalmente se utilizó para la evaluación de la depresión.', 'Se basa en cuatro principios generales entre los que se encuentra fomentar la discusión directa de la resistencia.', 'Incluye habilidades como la directividad, a través de preguntas cerradas.', NULL, 'a', NULL, NULL),
  (2021, 53, NULL, 'Existen diferentes pruebas de aprovechamiento escolar que pueden clasificarse según el continuo de especificidad-generalidad de la experiencia evaluada. De las siguientes, señale el tipo de pruebas que evalúan con mayor grado de especificidad:', 'Test de aptitud e inteligencia de tipo verbal.', 'Test transculturales de inteligencia.', 'Pruebas de desempeño sin lenguaje.', 'Pruebas de aprovechamiento de orientación amplia.', NULL, 'd', NULL, NULL),
  (2021, 54, NULL, 'En los test gráficos, como ejemplo de técnicas proyectivas, ¿mediante qué rasgo o aspecto gráfico del dibujo se puede llegar a concluir sobre la persona evaluada su tendencia a la fantasía, a la imaginación, al mundo de las ideas, en definitiva, su tendencia a buscar satisfacciones en el área de la fantasía más que en la realidad?:', 'El tamaño.', 'La proyección.', 'El emplazamiento.', 'La presión del trazo.', NULL, 'c', NULL, NULL),
  (2021, 55, NULL, 'Señale la opción correcta sobre la obtención de evidencias de validez de los test psicológicos:', 'Las evidencias sobre estructura interna se recogen mediante análisis factoriales y pueden realizarse desde la teoría de respuesta al ítem (TRI).', 'Las evidencias basadas en el contenido se recogen mediante análisis de temas, palabras, y formatos de los ítems, y pueden realizarse desde la teoría de respuesta al ítem (TRI).', 'Las evidencias de generalidad se recogen mediante análisis de consistencia y pueden realizarse desde la teoría de respuesta al ítem (TRI), desde la teoría clásica de los test (TCT), y desde la teoría conductual.', 'Las evidencias basadas en la relación con otras variables se recogen mediante modelos estructurales y pueden realizarse desde la teoría clásica de los test (TCT).', NULL, 'd', NULL, NULL),
  (2021, 56, NULL, '¿Qué tipo de escala se aplica cuando dada una lista de adjetivos se le pide al evaluado/a que considere, en cada uno de los adjetivos que se presentan, si son aplicables o no a la característica evaluada?:', 'Escala de intensidad.', 'Escala de orden.', 'Escala de elección no forzada.', 'Escala acumulativa.', NULL, 'd', NULL, NULL),
  (2021, 57, NULL, 'En el marco de los registros observacionales e instrumentos de observación, señale a qué prototipo de registro de observación nos referimos si en una tabla, en las columnas, se registran los niveles de respuesta y en las filas las unidades de conducta o textuales:', 'Registro semisistematizado.', 'Registro narrativo.', 'Registro de interacción.', 'Registro de apreciación.', NULL, 'a', NULL, NULL),
  (2021, 58, NULL, 'En las técnicas de evaluación narrativa, ¿qué fase NO forma parte del análisis textual de una narración o texto?:', 'Detección de macroestructuras.', 'Generación de síntesis discursiva.', 'Análisis de coherencias.', 'Análisis de las redundancias.', NULL, 'a', NULL, NULL),
  (2021, 60, NULL, '¿Qué evalúa el subtest “matrices” del WAIS-IV?:', 'Razonamiento abstracto no verbal.', 'Análisis de información visual diferenciando elementos básicos de arbitrarios.', 'Categorización lógica.', 'Percepción visual y praxis constructiva.', NULL, 'a', NULL, NULL),
  (2021, 61, NULL, '¿Cuál de los siguientes instrumentos se utiliza en la evaluación objetiva de la percepción visual?:', 'Punto de fusión “Flicker”.', 'Estesiómetro.', 'Test de precisión de Purdue.', 'Test de discriminación de dos puntos.', NULL, 'a', NULL, NULL),
  (2021, 62, NULL, '¿Qué indica el sujeto cuando responde a los ítems en una escala de tipo Likert de 0 a 100%, en la Escala de experiencias disociativas (DES) de Berstein y Putman (1986)?:', 'Grado de frecuencia e intensidad (frecuencia x intensidad), de las experiencias disociativas.', 'Porcentaje de tiempo que le acontecen experiencias disociativas.', 'Porcentaje de experiencias disociativas que cree que han ocurrido en el mes anterior.', 'Grado de intensidad con que le acontecen las experiencias disociativas.', NULL, 'b', NULL, NULL),
  (2021, 63, NULL, '¿Qué característica tiene el test Evaluación global de estrés postraumático (EGEP-5) de Crespo y colaboradores (2017)?:', 'El formato de los ítems es uniforme en todas sus escalas de respuesta.', 'La administración es preferentemente heteroaplicada e individual.', 'Incluye la evaluación de síntomas postraumáticos que no están incluidos en los criterios del DSM-5.', 'Se compone de dos secciones: una sobre acontecimientos traumáticos y otra sobre sintomatología.', NULL, 'c', NULL, NULL),
  (2021, 64, NULL, 'Uno de los sistemas de análisis más elaborado que se aplica a las historias de vida es el de coherencia narrativa (Adler y colaboradores, 2007). En el contexto de este modelo, señale cuáles son los indicadores o índices de coherencia en la historia de vida:', 'Orientación, estructura, afecto e integración.', 'Unidad, diálogo, atención y estructura.', 'Autodominio, estatus, responsabilidad y diálogo.', 'Valores, tema vital, autodominio y logro.', NULL, 'a', NULL, NULL),
  (2021, 65, NULL, 'En el Inventario de adjetivos para la evaluación de los trastornos de personalidad (IA-TP) (Tous y colaboradores, 2009), ¿qué escala se asocia al trastorno obsesivo-compulsivo de la personalidad?:', 'Personalidad inhibida.', 'Personalidad perfeccionista.', 'Personalidad sensible.', 'Personalidad respetuosa.', NULL, 'd', NULL, NULL),
  (2021, 66, NULL, 'El Inventario de evaluación de la personalidad (PAI):', 'Contiene 22 escalas: 4 de validez, 14 clínicas, 3 de consideraciones para el tratamiento y 1 de conflictos interpersonales.', 'Se considera que el protocolo no es válido a partir de 18 o más omisiones o respuestas dobles.', 'Su finalidad se circunscribe a la evaluación de los trastornos de personalidad.', 'Contiene una versión abreviada compuesta por los primeros 100 ítems.', NULL, 'b', NULL, NULL),
  (2021, 67, NULL, 'El Cuestionario breve de calidad de vida (CUBRECAVI) de Fernández-Ballesteros y colaboradores (1996):', 'Es aplicable a partir de los 55 años.', 'Evalúa 5 dimensiones de calidad de vida.', 'Evalúa la salud percibida a través de las escalas: energía, dolor, reacciones emocionales, sueño, aislamiento social y movilidad.', 'Se puede administrar mediante entrevista o cuestionario autoaplicado.', NULL, 'd', NULL, NULL),
  (2021, 68, NULL, '¿Cuál de los siguientes instrumentos se usa para valorar las actividades instrumentales de la vida diaria en personas en situación de dependencia?:', 'Índice de Katz.', 'Índice de Barthel.', 'Índice de Lawton y Brody.', 'Índice de Morton.', NULL, 'c', NULL, NULL),
  (2021, 69, NULL, 'Respecto de la Escala del síndrome positivo y negativo de la esquizofrenia (PANSS), señale la opción correcta:', 'La escala compuesta se obtiene restando de la puntuación de la escala negativa, la puntuación de la positiva (PANSS-C = PANSS-N – PANSS-P).', 'Cada ítem se evalúa mediante una escala tipo Likert de 5 puntos.', 'Desde una perspectiva categorial, clasifica la esquizofrenia en trastorno esquizofrénico positivo, negativo o mixto.', 'Se aplica teniendo como referencia la presentación sintomática en el último mes.', NULL, 'c', NULL, NULL),
  (2021, 70, NULL, 'Según la teoría triárquica de la inteligencia de Sternberg, la inteligencia puede ser comprendida en la interacción de tres aspectos. ¿Cuál de ellos explicaría las habilidades comprometidas en la capacidad creativa del individuo?:', 'La subteoría componencial.', 'La subteoría experiencial.', 'La subteoría contextual.', 'La subteoría de ejecución.', NULL, 'b', NULL, NULL),
  (2021, 72, NULL, 'En el marco del plan de muestreo observacional, señale cuál de las siguientes decisiones NO pertenece al nivel de muestreo intersesional:', 'Periodo de observación.', 'Número mínimo de sesiones.', 'Criterio de inicio de sesión.', 'Intervalos en que se divide la sesión de observación.', NULL, 'd', NULL, NULL),
  (2021, 73, NULL, 'La batería neuropsicológica infantil NEPSY-II cuenta, entre sus características, la siguiente:', 'Evalúa el reconocimiento facial de emociones y la teoría de la mente.', 'El tiempo de aplicación es de 30 a 45 minutos.', 'Contiene una forma para padres/madres.', 'Evalúa las capacidades cognitivas de niños pero no de adolescentes.', NULL, 'a', NULL, NULL),
  (2021, 74, NULL, 'Indique qué prueba NO se incluye dentro de las estructuras rítmicas de Stambak:', 'Reproducción gráfica de estructuras espaciales observadas.', 'Reproducción de estructuras temporales escuchadas.', 'Reproducción de estructuras espaciales dictadas.', 'Simbolización de estructuras espacio-temporales.', NULL, 'c', NULL, NULL),
  (2021, 75, NULL, 'Señale cuál de las siguientes pruebas de evaluación NO se emplea en niños de 3 años:', 'Escalas McCarthy de aptitudes y psicomotricidad (MSCA).', 'Test de Columbia (CMMS).', 'Batería de evaluación para niños de Kaufman y Kaufman (K-ABC).', 'Inventario de desarrollo Battelle.', NULL, 'b', NULL, NULL),
  (2021, 76, NULL, 'Indique la opción correcta con respecto al WPPSI-IV. En el nivel inferior de aplicación (2:6 a 3:11 años):', 'Se utilizan los test: matrices, búsqueda de animales, semejanzas, conceptos, cancelación y vocabulario.', 'Se obtienen los índices de comprensión verbal, visoespacial y de memoria de trabajo.', 'Las escalas secundarias dan lugar al índice de competencia cognitiva.', 'Se incluyen los índices de razonamiento fluido y de velocidad de procesamiento.', NULL, 'b', NULL, NULL),
  (2021, 77, NULL, 'Una de las tres aptitudes intelectuales de segundo orden que evalúa el BAS-II es el razonamiento perceptivo ¿Mediante qué test se calcula este índice?:', 'Test de copia y test de cubos.', 'Test de semejanzas gráficas y test de cubos.', 'Test de conceptos numéricos y test de semejanzas gráficas.', 'Test de cubos y test de conceptos numéricos.', NULL, 'c', NULL, NULL),
  (2021, 78, NULL, 'En la evaluación de la enuresis funcional en la infancia, la Escala de tolerancia materna de Morgan y Young se ha relacionado con:', 'Predicción del abandono prematuro de la intervención.', 'Implicación de la madre en el manejo de la intervención.', 'Grado de adherencia del niño a la intervención.', 'Eficacia de la intervención en casos resistentes.', NULL, 'a', NULL, NULL),
  (2021, 79, NULL, 'Con relación al curso de los síntomas del espectro de la esquizofrenia y otros trastornos psicóticos, señale la opción correcta (Austin y colaboradores, 2015; Haro y colaboradores., 2015; DSM-5):', 'Algo más de la mitad de los pacientes adultos con un diagnóstico de esquizofrenia presentan síntomas psicóticos persistentes durante un promedio de casi 10 años (Haro y colaboradores., 2015).', 'En personas que habían tenido un primer episodio psicótico se encontró que cerca de la mitad mostraba una respuesta negativa (incremento de los síntomas) durante los primeros cinco años seguida de un mantenimiento sin síntomas en los cinco años restantes (Austin y colaboradores, 2015).', 'En personas que habían tenido un primer episodio psicótico se encontró que un 15% mostraba un aumento inicial de los síntomas durante los dos primeros años, seguido de un decremento constante durante ocho años (Austin y colaboradores, 2015).', 'El diagnóstico del trastorno psicótico breve requiere la remisión completa de todos los síntomas y un retorno parcial al nivel de funcionamiento premórbido antes de transcurrido un mes desde el inicio del trastorno (DSM-5).', NULL, 'a', NULL, NULL),
  (2021, 81, NULL, '¿A partir de qué cantidad de consumo de cafeína se considera que, en general, la misma tiene efectos negativos en el organismo en población adulta sana?:', 'A partir de 100 mg. de cafeína al día.', 'A partir de 300 mg. de cafeína al día.', 'A partir de 400 mg. de cafeína al día.', 'A partir de 1.000 mg. de cafeína al día.', NULL, 'c', NULL, NULL),
  (2021, 82, NULL, 'Según el DSM-5, el diagnóstico de trastorno disfórico premenstrual requiere que los síntomas se hayan confirmado mediante:', 'Evaluaciones diarias prospectivas de al menos dos ciclos sintomáticos.', 'Evaluaciones diarias prospectivas de al menos tres ciclos sintomáticos.', 'Evaluaciones diarias retrospectivas de al menos dos ciclos sintomáticos.', 'Evaluaciones diarias retrospectivas de al menos tres ciclos sintomáticos.', NULL, 'a', NULL, NULL),
  (2021, 83, NULL, 'Un sujeto que, a raíz de un suceso estresante, tiene sensación de que el tiempo transcurre muy despacio, se siente anestesiado, presenta momentos de parálisis y de amnesia, síntomas todos ellos que, en general, desaparecen en menos de un mes; padece con más probabilidad:', 'Trastorno de síntomas somáticos.', 'Trastorno adaptativo con síntomas mixtos.', 'Reacción disociativa aguda a sucesos estresantes.', 'Trastorno de estrés agudo.', NULL, 'c', NULL, NULL),
  (2021, 84, NULL, 'Según el DSM-5, en el trastorno depresivo mayor con características melancólicas:', 'Está presente la anhedonia o la falta de reactividad a sucesos positivos generalmente placenteros.', 'Se da mayor sintomatología en otoño/invierno.', 'El estado de ánimo deprimido es más acusado por la tarde.', 'Se da un patrón prolongado de sensibilidad o rechazo interpersonal percibido.', NULL, 'a', NULL, NULL),
  (2021, 85, NULL, 'Las “sincinesias” son alteraciones que se caracterizan por:', 'Movimientos involuntarios parásitos o accesorios que se dan como consecuencia de otro movimiento voluntario.', 'Efectos iatrogénicos que se produce tras la administración prolongada de un fármaco.', 'Movimientos espasmódicos rápidos, breves y sin objetivo.', 'Contracciones musculares mantenidas en el tiempo.', NULL, 'a', NULL, NULL),
  (2021, 86, NULL, 'Las alucinaciones olfativas son más frecuentes en:', 'Delirium.', 'Episodio maníaco.', 'Epilepsia.', 'Alucinosis alcohólica.', NULL, 'c', NULL, NULL),
  (2021, 87, NULL, 'En lo relativo al diagnóstico diferencial de los trastornos neurocognitivos, señale la respuesta FALSA:', 'El trastorno neurocognitivo vascular mayor o leve puramente subcortical puede tener un curso lentamente progresivo que emula al trastorno neurocognitivo debido a la enfermedad de Alzheimer.', 'Mientras que en el trastorno neurocognitivo vascular mayor o leve aparecen déficits en la función ejecutiva y el lenguaje, el inicio insidioso y la progresión gradual de los síntomas comportamentales o la disfunción del lenguaje son más característicos del trastorno neurocognitivo frontotemporal y no son típicos de la etiología vascular.', 'En el trastorno neurocognitivo frontotemporal mayor o leve la supervivencia es mayor y el declive más lento que en la enfermedad de Alzheimer típica.', 'El diagnóstico de delirium por abstinencia de sustancias solamente debe establecerse en lugar de un diagnóstico de síndrome de abstinencia cuando los síntomas relativos a una alteración de la atención y a una alteración cognitiva adicional predominen en el cuadro clínico y sean suficientemente graves para exigir atención clínica.', NULL, 'c', NULL, NULL),
  (2021, 88, NULL, 'En cuanto al diagnóstico de los trastornos neurocognitivos, señale la respuesta FALSA:', 'El trastorno neurocognitivo frontotemporal mayor o leve se manifiesta principalmente a través de cambios progresivos en el comportamiento y déficits en el lenguaje.', 'Además de una disfunción cognitiva progresiva, el trastorno neurocognitivo mayor o leve con cuerpos de Lewy incluye alucinaciones visuales recurrentes y síntomas espontáneos de parkinsonismo.', 'La incapacidad para enfocar y mover los ojos correctamente es una de las señales típicas de la enfermedad de Parkinson.', 'La mayoría de las personas con delirium presenta una recuperación completa con o sin tratamiento, si bien la identificación e intervención temprana habitualmente reduce la duración del delirium.', NULL, 'c', NULL, NULL),
  (2021, 89, NULL, 'En el tratamiento de los trastornos neurocognitivos, señale la respuesta correcta:', 'El uso de antipsicóticos en pacientes con demencia produce efectos adversos muy notables.', 'La intervención farmacológica en las fases más avanzadas de la enfermedad se centra en la administración de fármacos inhibidores de la acetilcolinesterasa (donezepilo, rivastigmina o galantamina).', 'En las fases leves y moderadas de la enfermedad, la intervención farmacológica se basa en fármacos antagonistas del glutamato (memantina).', 'El uso de fármacos antipsicóticos está especialmente indicado en pacientes con demencia por cuerpos de Lewy.', NULL, 'a', NULL, NULL),
  (2021, 90, NULL, 'Sobre la demencia vascular es correcto afirmar que:', 'Suele presentar un curso de tipo fluctuante y evoluciona en forma de brotes hacia un deterioro progresivo.', 'Es el prototipo de demencia cortical.', 'Su déficit más significativo se encuentra en la memoria episódica, especialmente en el recuerdo demorado.', 'Uno de los criterios de la International Society for Vascular Behavioral and Cognitive Disorders (VASCOG) para su diagnóstico, a diferencia de los criterios del National Institute of Neurological Disorders and Stroke Association Association Internationale pour la Recherche et l’Enseignement en Neurosciences (NINDS-AIREN), es que se requiere la afectación de dos o más dominios, siendo uno de ellos la memoria.', NULL, 'a', NULL, NULL),
  (2021, 91, NULL, 'La ecmnesia es una alteración que se caracteriza por:', 'Considerar recuerdos del propio pasado como si fueran vivencias del presente.', 'Un falso reconocimiento en el que el individuo cree que una persona familiar es en realidad desconocida.', 'Un falso reconocimiento en el que el individuo cree que es la primera vez que vivencia una situación.', 'Una experiencia en la que un recuerdo se vivencia como una producción o idea original.', NULL, 'a', NULL, NULL),
  (2021, 92, NULL, 'Una modalidad de alucinación en la que la convicción de la realidad “exterior” de la imagen alucinada es escasa o nula es la siguiente:', 'Pseudoalucinación.', 'Alucinación funcional.', 'Imagen alucinante.', 'Imagen refleja.', NULL, 'a', NULL, NULL),
  (2021, 93, NULL, 'Respecto de la bulimia nerviosa (BN), señale la opción FALSA:', 'Una desviación temprana en el peso, tanto por exceso como por defecto, posiblemente asociada a alteraciones metabólicas tempranas, constituye un predictor de padecimiento posterior de BN.', 'Entre los factores psicológicos asociados a la BN destaca el rasgo de evitación del daño.', 'Las personas con BN presentan importantes dificultades a la hora de afrontar emociones intensas positivas.', 'No parece existir ningún riesgo de BN asociado a la prematuridad del nacimiento.', NULL, 'd', NULL, NULL),
  (2021, 94, NULL, 'La experiencia conocida como laguna temporal se define como:', 'Una alteración de la memoria caracterizada por amnesia selectiva.', 'Una alteración de la orientación temporal que no afecta a la orientación espacial ni personal.', 'Una alteración de la atención que se puede producir mientras se realiza una tarea automática.', 'Una alteración de la conciencia que cursa con disminución del estado de alerta.', NULL, 'c', NULL, NULL),
  (2021, 95, NULL, 'La atmósfera delirante es una alteración que se caracteriza por ser:', 'Una idea delirante secundaria sobre el significado del mundo.', 'Una idea delirante primaria en la que la persona tiene la experiencia de que el mundo ha cambiado.', 'Una idea delirante secundaria en la que la persona varía sus interpretaciones de las percepciones.', 'Una idea delirante primaria asociada a la reconstrucción delirante de recuerdos.', NULL, 'b', NULL, NULL),
  (2021, 96, NULL, 'Las contracciones incontrolables, violentas y difusas de la musculatura voluntaria se denominan:', 'Tics.', 'Automatismos.', 'Acatisia.', 'Convulsiones.', NULL, 'd', NULL, NULL),
  (2021, 97, NULL, 'Teniendo en cuenta los criterios diagnósticos del DSM-5 respecto del trastorno de ansiedad por separación (TAS), señale la afirmación correcta:', 'Para poder realizar un diagnóstico de TAS en niños y adultos, los síntomas tienen que haber estado presentes durante al menos 4 meses.', 'Para poder realizar un diagnóstico de TAS en niños, los síntomas tienen que haber estado presentes durante al menos 6 meses.', 'Es suficiente que los síntomas hayan estado presentes 4 semanas para hacer un diagnóstico de TAS, tanto en niños como en adultos.', 'Para poder realizar un diagnóstico de TAS en adultos, los síntomas tienen que haber estado presentes al menos 6 meses.', NULL, 'd', NULL, NULL),
  (2021, 98, NULL, 'Señale cuál de los siguientes modelos etiológicos sobre el trastorno de pánico confiere una especial relevancia al concepto de autoeficacia con respecto al pánico:', 'El modelo integrador cognitivo de Casey, Oei y Newcombe (2004).', 'El modelo cognitivo de Clark (1986).', 'El modelo integrador de Barlow (Barlow y Durand, 2003).', 'El modelo de aprendizaje interoceptivo de Wolpe y Rowan (1988).', NULL, 'a', NULL, NULL),
  (2021, 99, NULL, 'En relación con el trastorno de ansiedad generalizada, señale la afirmación correcta sobre el papel de la preocupación en el modelo de Borkovec y colaboradores:', 'La preocupación se mantiene porque reduce la ansiedad y la activación fisiológica asociada a las imágenes negativas.', 'Las creencias negativas sobre la preocupación activan las preocupaciones tipo 2.', 'La aprensión ansiosa está en la base de la preocupación.', 'La intolerancia a la incertidumbre activa la cadena de preocupación y la evitación cognitiva.', NULL, 'a', NULL, NULL),
  (2021, 100, NULL, 'Respecto del trastorno bipolar I, señale la afirmación correcta:', 'El comienzo del trastorno se circunscribe a los primeros años de la edad adulta.', 'El comienzo del trastorno puede darse a lo largo de todo el ciclo vital.', 'Solo un 30% (aproximadamente) de los episodios maníacos ocurre inmediatamente antes de un episodio depresivo mayor.', 'Los pacientes que tienen 3 o más episodios (de depresión mayor, manía o hipomanía) en un año, se les aplicaría el especificador “con ciclos rápidos”.', NULL, 'b', NULL, NULL),
  (2021, 101, NULL, 'Si un paciente presenta uno o más síntomas somáticos que causan malestar y pensamientos desproporcionados y persistentes sobre la gravedad de los propios síntomas y un grado persistentemente elevado de ansiedad acerca de la salud o de los síntomas; según el DSM-5, ¿qué diagnóstico debería recibir?:', 'Trastorno de síntomas somáticos.', 'Trastorno de ansiedad por la enfermedad.', 'Hipocondría.', 'Trastorno de pánico.', NULL, 'a', NULL, NULL),
  (2021, 102, NULL, 'La CIE 11 incluye entre sus novedades el trastorno de disforia por la integridad corporal (body integrity dysphoria); señale cuál es su característica principal:', 'El malestar por alguna parte del cuerpo que se percibe como no acorde con la propia identidad.', 'El deseo intenso y persistente de tener una discapacidad física importante.', 'Tener una intensa sensación de despersonalización y disgregación de las diferentes partes del cuerpo.', 'Sentir un intenso miedo a que alguna parte del cuerpo (en especial una extremidad) se disgregue del propio cuerpo.', NULL, 'b', NULL, NULL),
  (2021, 103, NULL, 'Respecto del trastorno facticio aplicado a otros (DSM-5), indique la respuesta FALSA:', 'En el DSM-5 está incluido dentro de los trastornos de síntomas somáticos.', 'Implica la falsificación de signos o síntomas físicos o psicológicos en otro individuo, asociados a un engaño identificado.', 'El diagnóstico se aplica tanto al autor como a la víctima.', 'El comportamiento engañoso es evidente incluso en ausencia de recompensa externa obvia.', NULL, 'c', NULL, NULL),
  (2021, 104, NULL, 'En general, cabe afirmar que las alucinaciones no se fundamentan en estímulos realmente existentes fuera del individuo; no obstante (señale la opción FALSA):', 'Las pseudoalucinaciones son reconocidas como subjetivas y ubicadas dentro del interior del sujeto.', 'En las alucinaciones funcionales sí hay, de algún modo, intervención estimular, y la alucinación desaparece cuando desaparece el estímulo.', 'Las alucinaciones funcionales son frecuentes en la esquizofrenia.', 'En las alucinaciones negativas el sujeto no percibe el objeto y se comporta, en consecuencia, como si su ausencia fuera real.', NULL, 'd', NULL, NULL),
  (2021, 105, NULL, 'Según el DSM-5, ¿en cuál de las siguientes disfunciones sexuales se especifica que “la evaluación de la deficiencia la hace el clínico”:', 'Trastorno de deseo sexual hipoactivo en el varón.', 'Trastorno del interés/excitación sexual femenino.', 'Eyaculación prematura (precoz).', 'Eyaculación retardada.', NULL, 'a', NULL, NULL),
  (2021, 106, NULL, 'Un trastorno del lenguaje no fluente, con buena repetición, es característico de la afasia:', 'De conducción.', 'De Broca.', 'Transcortical motora.', 'De Wernicke.', NULL, 'c', NULL, NULL),
  (2021, 107, NULL, 'Señale cuál de los siguientes aspectos constituye un factor mantenedor de los trastornos de la conducta alimentaria (Fairburn y colaboradores, 2003):', 'Separación o pérdida.', 'Críticas sobre el cuerpo.', 'Aislamiento social.', 'Enfermedad adelgazante.', NULL, 'c', NULL, NULL),
  (2021, 108, NULL, 'Según la teoría de los estilos de respuesta de Nolen-Hoeksema, la intensidad y duración de los síntomas depresivos se verá agravada cuando ante los primeros síntomas:', 'La persona realice respuestas evitativas.', 'La persona adopte un estilo de respuesta rumiativo.', 'La persona realice conductas y ponga en marcha pensamientos de distracción.', 'La persona realice atribuciones fatalistas sobre lo ocurrido.', NULL, 'b', NULL, NULL),
  (2021, 109, NULL, '¿Cuál de las siguientes NO es una de las ideas principales del modelo de Barlow (1986) para la disfunción eréctil?:', 'La presentación de distractores de carácter neutro (no sexual) disminuye la activación de las personas con disfunción.', 'Las personas funcionales y las disfuncionales reaccionan de igual manera a los distractores cuando son estímulos sexuales.', 'Las personas con disfunción se distraen de las claves eróticas de la situación cuando aparecen estímulos distractores que suponen una demanda de rendimiento sexual.', 'En las personas sin disfunción la activación sexual se ve facilitada por los estímulos sexuales que implican demanda de rendimiento sexual.', NULL, 'b', NULL, NULL),
  (2021, 110, NULL, 'Respecto de la disforia de género, señale la opción correcta (DSM-5):', 'Los sujetos con trastorno somático del desarrollo sexual presentan correlaciones altas de la identidad sexual final con el grado de producción y de utilización prenatal de andrógenos.', 'En general, la evidencia actual resulta suficiente para etiquetar la disforia de género sin trastorno del desarrollo sexual como una forma de intersexualidad limitada al sistema nervioso central.', 'La preocupación relacionada con deseo de cambio de sexo puede aparecer a cualquier edad a partir de los 6 años, aproximadamente.', 'La conducta sexual atípica, por sí misma, no debería interpretarse como un indicador de disforia de género presente o futura.', NULL, 'd', NULL, NULL),
  (2021, 111, NULL, 'Respecto de los ataques de pánico, señale la opción FALSA:', 'Una afección médica que puede causar (asociarse a) ataques de pánico es el hiperparatiroidismo.', 'Las pruebas de laboratorio (p. ej., los niveles de calcio en el suero) han mostrado utilidad para determinar el papel etiológico de las afecciones médicas en los ataques de pánico.', 'Los ataques de pánico se asocian con una mayor probabilidad de desarrollar, posteriormente, trastornos bipolares.', 'La edad de aparición de los ataques de pánico no se ha mostrado útil de cara al análisis de las hipótesis etiológicas en los pacientes.', NULL, 'd', NULL, NULL),
  (2021, 112, NULL, '¿Cuál de los siguientes es considerado, según el DSM-5, un trastorno algolágnico?:', 'El trastorno del sadismo sexual.', 'El trastorno de síntomas somáticos con predominio de dolor.', 'El trastorno de dolor génito-pélvico.', 'El trastorno facticio.', NULL, 'a', NULL, NULL),
  (2021, 113, NULL, 'Señale la afirmación correcta respecto a la fobia específica:', 'Los ataques de pánico característicos de la fobia específica son cualitativamente diferentes de los del trastorno de pánico.', 'La mayoría de los individuos con fobia específica siente temor ante un solo objeto o situación y, frecuentemente, experimentan ataques de pánico inesperados (DSM-5).', 'Todas las fobias específicas presentan un patrón de respuesta cardiovascular semejante.', 'Las diferencias entre los ataques de pánico en el trastorno de pánico y los que se dan en el marco de las fobias específicas residen en la frecuencia y en la gravedad.', NULL, 'd', NULL, NULL),
  (2021, 114, NULL, 'Señale la afirmación correcta respecto del trastorno dismórfico corporal (TDC), según el DSM-5:', 'Las tasas de comorbilidad más altas se producen con los trastornos alimentarios.', 'Se ha asociado con abandono y abuso en la infancia, pero no con predisposiciones biológicas.', 'La dismorfia de tipo muscular es común en hombres y en mujeres.', 'Las características clínicas principales son similares en hombres y en mujeres.', NULL, 'd', NULL, NULL),
  (2021, 115, NULL, 'Señale cuál de los siguientes trastornos resulta menos comórbido con la cleptomanía (DSM-5):', 'Trastorno depresivo mayor.', 'Trastorno bipolar.', 'Trastornos de la conducta alimentaria.', 'Trastorno esquizofrénico.', NULL, 'd', NULL, NULL),
  (2021, 116, NULL, 'En el marco de los trastornos de la conducta alimentaria, dentro de las distorsiones cognitivas conocidas como “La docena sucia”, señale cómo se denomina a la distorsión: “Inferir que el aspecto de uno ha sido la causa de algo que no quería que ocurriera”:', 'El espejo malhumorado.', 'Expansión de la fealdad.', 'Juego de culpa.', 'La atadura de la belleza.', NULL, 'c', NULL, NULL),
  (2021, 117, NULL, 'Según el DSM-5 la especificación “en remisión total” para un trastorno depresivo indica que no ha habido signos o síntomas significativos del trastorno durante al menos:', '1 año.', 'Los últimos 4 meses.', 'Los últimos 2 meses.', 'Los últimos 6 meses.', NULL, 'c', NULL, NULL),
  (2021, 118, NULL, 'Por lo que se refiere a los marcadores diagnósticos de los trastornos del despertar del sueño NO REM, cabe afirmar lo siguiente:', 'La inestabilidad del sueño profundo NO REM, tal como se muestra en la polisomnografía, es un marcador muy fiable de cara al diagnóstico y diagnóstico diferencial del sonambulismo.', 'Los despertares de sueño NO REM de los terrores nocturnos se inician bruscamente, sin cambios autonómicos anticipatorios.', 'Los trastornos del despertar del sueño NO REM se presentan con mayor frecuencia durante el sueño de ondas rápidas.', 'Existen indicadores polisomnográficos fiables de la tendencia a experimentar terrores nocturnos cuando se realizan registros fuera del episodio.', NULL, 'b', NULL, NULL),
  (2021, 119, NULL, 'Respecto de los terrores nocturnos, cabe afirmar lo siguiente:', 'Normalmente el sujeto se despierta y tarda en dormirse debido a la ansiedad.', 'La prevalencia de los episodios de terrores nocturnos (vs. el trastorno de terrores nocturnos) es de, aproximadamente, un 0,5% en la población general.', 'Los estudios con gemelos apuntan a la ausencia de un componente genético por lo que se refiere a su etiología.', 'Entre los niños son más frecuentes en varones que en mujeres, mientras que la proporción tiende a igualarse en la edad adulta.', NULL, 'd', NULL, NULL),
  (2021, 120, NULL, 'El inicio de la hipersomnia suele producirse:', 'En la adolescencia o en los primeros años de la vida adulta.', 'Principalmente a partir de los 65 años.', 'A cualquier edad.', 'Típicamente en la primera infancia, entre los 0 y los 6 años de edad.', NULL, 'a', NULL, NULL),
  (2021, 121, NULL, 'En la evaluación de los trastornos del sueño, la Escala de Epworth (ESS) nos permite:', 'Evaluar el grado de severidad del insomnio del paciente.', 'Evaluar el grado de somnolencia diurna del paciente.', 'Evaluar el grado de intensidad del ronquido del paciente.', 'Evaluar la probabilidad de que sufra un trastorno del sueño REM.', NULL, 'b', NULL, NULL),
  (2021, 122, NULL, 'Señale en cuál de los siguientes diagnósticos de parafilia se exige que el sujeto del diagnóstico posea la mayoría de edad:', 'Trastorno de pedofilia.', 'Trastorno de exhibicionismo.', 'Trastorno de fetichismo.', 'Trastorno de voyeurismo.', NULL, 'd', NULL, NULL),
  (2021, 123, NULL, 'Respecto del trastorno psicótico breve o agudo y transitorio, cabe afirmar lo siguiente (DSM-5):', 'Se estima una prevalencia vital del 4,6% en población general, con una incidencia superior en los hombres.', 'Se estima una prevalencia vital del 0,3% con una incidencia superior en mujeres.', 'Se estima que representa el 9% de los casos de primer episodio de psicosis, con mayor incidencia en mujeres.', 'Se estima una prevalencia vital del 0,5-1,5%, con una incidencia superior en hombres.', NULL, 'c', NULL, NULL),
  (2021, 124, NULL, 'Según el DSM-5, ¿cuál de los siguientes criterios debe cumplirse para diagnosticar una disforia de género en niños?:', 'Un fuerte deseo por poseer los caracteres sexuales tanto primarios como secundarios, correspondientes al género que se siente.', 'Una marcada incongruencia entre el género que uno siente o expresa y sus caracteres sexuales primarios o secundarios.', 'Preferencias marcadas y persistentes por el papel del otro género o fantasías de pertenecer al otro género.', 'Un poderoso deseo de ser del otro género o una insistencia en que él o ella es del género opuesto (o de un género alternativo distinto del que se le asignó).', NULL, 'd', NULL, NULL),
  (2021, 125, NULL, 'Señale la afirmación correcta respecto del diagnóstico diferencial entre fobia específica tipo situacional y agorafobia, según los criterios del DSM-5:', 'Si la persona teme solo a una situación típicamente agorafóbica, se aconseja realizar un diagnóstico de fobia específica situacional.', 'Si la persona está preocupada por el daño que le puede hacer el objeto o situación, el diagnóstico de agorafobia estaría justificado.', 'Si la persona teme una situación típicamente agorafóbica en concreto, se recomienda realizar un diagnóstico de agorafobia.', 'Si el único estímulo fóbico es de tipo situacional (p. ej., sitios cerrados), el diagnóstico de agorafobia estaría justificado.', NULL, 'a', NULL, NULL),
  (2021, 126, NULL, 'En la anorexia nerviosa hay un peso corporal significativamente bajo, que se establece a partir de un índice de masa corporal (IMC) por debajo de:', 'En adultos, 18; en niños (IMC para la edad), percentil 10.', 'En adultos, 17; en niños (IMC para la edad), percentil 8.', 'En adultos, 18,5; en niños (IMC para la edad), percentil 10.', 'En adultos, 18,5; en niños (IMC para la edad), percentil 5.', NULL, 'd', NULL, NULL),
  (2021, 127, NULL, 'A diferencia de la depresión unipolar, en la depresión bipolar:', 'La edad de inicio es mayor.', 'El número de episodios es menor.', 'La duración de los episodios es mayor.', 'Existe mayor riesgo de padecer síntomas atípicos.', NULL, 'd', NULL, NULL),
  (2021, 128, NULL, 'Señale cuál de las siguientes opciones hace alusión a un objetivo propio de la terapia dialéctico-conductual de Linehan para el trastorno límite de la personalidad:', 'Mejorar la eficacia interpersonal.', 'Cuestionar los patrones de pensamiento disfuncional.', 'Modificar los esquemas tempranos desadaptativos.', 'Buscar la causa del malestar.', NULL, 'a', NULL, NULL),
  (2021, 130, NULL, '¿Qué limitación se ha descrito en relación al tratamiento cognitivo-conductual para el trastorno de atracones?:', 'No se mantiene a largo plazo la reducción del peso de los pacientes.', 'No mejora la calidad de vida de los pacientes.', 'No se reducen los síntomas psicopatológicos de los pacientes.', 'No se reduce la frecuencia de los atracones de los pacientes.', NULL, 'a', NULL, NULL),
  (2021, 131, NULL, '¿Cuál de las siguientes técnicas se emplea preferente y específicamente en el tratamiento de la tricotilomanía y la excoriación?:', 'Reestructuración cognitiva de creencias disfuncionales.', 'La inversión de hábito.', 'Estrategias para incrementar la motivación hacia el cambio.', 'Experimentos conductuales.', NULL, 'b', NULL, NULL),
  (2021, 132, NULL, '¿Cuál es el objetivo principal de la terapia cognitiva de las creencias disfuncionales en el trastorno obsesivo-compulsivo?:', 'Modificar la visión que tiene la persona del trastorno.', 'Modificar el modo en que la persona valora e interpreta sus pensamientos intrusos y obsesivos.', 'La aceptación de las obsesiones y pensamientos intrusos.', 'Facilitar la habituación a las obsesiones.', NULL, 'b', NULL, NULL),
  (2021, 133, NULL, 'Solicitamos a un paciente diagnosticado de trastorno obsesivo-compulsivo que durante 10 minutos trate de no pensar en un gato blanco, que registre la frecuencia con que lo piensa durante el ejercicio, y la compare con la frecuencia de ese pensamiento a lo largo del día. Con este experimento, probablemente, estemos tratando de trabajar la siguiente creencia:', 'Fusión pensamiento acción tipo probabilidad.', 'Fusión pensamiento acción tipo moral.', 'Responsabilidad excesiva.', 'Sobrestimación de la importancia de los pensamientos.', NULL, 'd', NULL, NULL),
  (2021, 136, NULL, 'Señale en qué tratamiento psicológico para la psicosis uno de los elementos terapéuticos es “Ayudar a crear un sentido trascendental del yo”:', 'Terapia metacognitiva para la psicosis.', 'Terapia de aceptación y compromiso.', 'Terapia centrada en la compasión.', 'Terapia cognitiva basada en mindfulness.', NULL, 'b', NULL, NULL),
  (2021, 137, NULL, '¿Qué intervención está indicada y se diseñó especialmente para la prevención de las recaídas en los trastornos depresivos?:', 'Activación conductual.', 'Terapia interpersonal.', 'Terapia cognitiva de la depresión de Beck.', 'Terapia cognitiva basada en mindfulness.', NULL, 'd', NULL, NULL),
  (2021, 138, NULL, 'La terapia familiar o terapia basada en la familia (FBT) del Instituto Maudsley consta de varias fases; indique la opción FALSA:', 'Completo control de los padres.', 'Distanciamiento respecto de los padres.', 'Retorno gradual del control al adolescente.', 'Establecer una independencia saludable.', NULL, 'b', NULL, NULL),
  (2021, 139, NULL, 'Durante la intervención con pacientes psicóticos y desde el modelo de Terapia cognitiva basada en la persona (p. ej., Chadwick, 2006), ¿qué acción se considera más adecuada sobre los esquemas personales negativos?:', 'Facilitar que la persona reconozca las experiencias como parte de la propia identidad o el yo.', 'Confrontar la evitación experiencial para reducir el miedo a las experiencias esquemáticas negativas.', 'Identificar las experiencias esquemáticas negativas y abordarlas como las distorsiones cognitivas que son.', 'No cuestionar las experiencias esquemáticas negativas, facilitando ser consciente de las mismas.', NULL, 'd', NULL, NULL),
  (2021, 140, NULL, 'Señale cuál de las siguientes afirmaciones sobre entrevistas estructuradas o semiestructuradas es FALSA:', 'La SCID-5 tiene cinco versiones: tres para evaluar los diagnósticos generales agrupados en diez módulos y dos para los trastornos de personalidad.', 'La SADS permite realizar el diagnóstico y realizar el historial médico.', 'La KSADS-5 permite la evaluación de niños y adolescentes entre 6 y 18 años siguiendo criterios DSM-5.', 'La CIDI 3.0 es una entrevista semiestructurada que constituye una herramienta de ayuda diagnóstica de las principales categorías incluidas en la CIE-10 (excluido el riesgo de suicidio) y que se compone de 41 secciones.', NULL, 'd', NULL, NULL),
  (2021, 141, NULL, '¿Entre qué valores se recomienda la recuperación de peso en personas con anorexia nerviosa hospitalizadas?:', '0,2 y 0,5 kg. por semana.', '0,5 y 1 kg. por semana.', '1,5 y 2,5 kg. por semana.', 'No hay recomendaciones a este respecto.', NULL, 'b', NULL, NULL),
  (2021, 142, NULL, '¿Qué terapia está más recomendada para personas que tienen el trastorno de estrés postraumático y sentimientos de culpa asociados?:', 'La terapia de desensibilización y reprocesamiento por movimientos oculares (EMDR).', 'La terapia dialéctica conductual.', 'La terapia de procesamiento cognitivo.', 'La terapia centrada en el presente.', NULL, 'c', NULL, NULL),
  (2021, 143, NULL, '¿Cuál de los siguientes tratamientos para el trastorno de estrés postraumático tiene un mayor apoyo empírico?:', 'La terapia de exposición prolongada.', 'La terapia dialéctica conductual.', 'El entrenamiento en relajación muscular progresiva.', 'La terapia centrada en el presente.', NULL, 'a', NULL, NULL),
  (2021, 144, NULL, 'Respecto del trastorno denominado “Factores psicológicos que influyen en otras afecciones médicas” (DSM-5), y por lo que se refiere al nivel de gravedad, cuando dichos factores psicológicos se asocian a un empeoramiento del cuadro médico que requiere acudir a un servicio de urgencias médicas, hemos de realizar la especificación siguiente:', 'Leve.', 'Moderada.', 'Grave.', 'Extrema.', NULL, 'c', NULL, NULL),
  (2021, 145, NULL, 'En la terapia de procesamiento cognitivo (Resick y colaboradores), se retan o desafían los significados del trauma en algunas áreas en las que los pacientes tienen más dificultades; señale cuáles:', 'Autoestima, seguridad, sentimientos de vacío y embotamiento afectivo.', 'Confianza y amnesia psicógena.', 'Seguridad y sentimientos de culpa.', 'Seguridad, confianza, poder/control, autoestima e intimidad.', NULL, 'd', NULL, NULL),
  (2021, 146, NULL, '¿Cuál de los siguientes componentes forman parte de la técnica RGINA (reducción gradual de ingestión de nicotina y alquitrán) para el tratamiento del tabaquismo?:', 'Gráfica de progresos y entrenamiento en relajación.', 'Reducción progresiva del número de cigarrillos y cambio semanal de marca a otra con menor grado de nicotina.', 'Reducción progresiva del número de cigarrillos y entrenamiento en habilidades de afrontamiento.', 'Cambio semanal de marca a otra con menor grado de nicotina y entrenamiento en relajación.', NULL, 'b', NULL, NULL),
  (2021, 147, NULL, '¿En combinación con qué protocolo, el manejo de contingencias mediante incentivos ha mostrado buenos resultados en el tratamiento de la adicción a la cocaína?:', 'Entrevista motivacional.', 'Terapia familiar conductual.', 'Programa de reforzamiento comunitario (CRA).', 'Terapia de exposición a señales.', NULL, 'c', NULL, NULL),
  (2021, 148, NULL, 'En el tratamiento de la bulimia nerviosa y en base a la evidencia empírica, ¿qué terapia se puede considerar como alternativa a la terapia cognitivo-conductual?:', 'La psicoterapia focal.', 'La psicoterapia cognitivo-analítica.', 'La terapia interpersonal.', 'La terapia familiar sistémica.', NULL, 'c', NULL, NULL),
  (2021, 149, NULL, 'Señale qué elemento NO forma parte del modelo del tratamiento cognitivo-conductual grupal para el trastorno por hipersexualidad de Hallberg et al. (2019):', 'Psicoeducación básica.', 'Técnicas de gestión de impulsos.', 'Exposición y prevención de respuesta.', 'Activación conductual interpersonal.', NULL, 'c', NULL, NULL),
  (2021, 150, NULL, 'El procedimiento denominado “thinking aloud” (pensar en voz alta) en el tratamiento del juego patológico se utiliza para:', 'Identificar los pensamientos irracionales que acompañan a la conducta de jugar.', 'Controlar los estímulos condicionados asociados a la conducta de jugar.', 'Modificar los patrones de juego compulsivos de los jugadores patológicos.', 'Identificar los determinantes de las recaídas pasadas en la conducta de jugar.', NULL, 'a', NULL, NULL),
  (2021, 152, NULL, 'El uso de estrógenos o antiandrógenos en el abordaje médico de algunas personas con disforia de género, suele tener como efecto:', 'Más síntomas de ansiedad.', 'Peor estado de ánimo y empeoramiento de la calidad de vida.', 'Mayor aversión hacia sus genitales.', 'Reducir la libido, aunque en algunos casos se ha encontrado un mayor interés en el sexo.', NULL, 'd', NULL, NULL),
  (2021, 153, NULL, 'El objetivo principal del tratamiento psicológico de los trastornos parafílicos suele ser:', 'La eliminación del interés sexual específico que está a la base de la parafilia.', 'Evitar o disminuir la probabilidad de que se realice el comportamiento, que puede llevar incluso a un acto delictivo, o la reincidencia.', 'La disminución del deseo o pulsión sexual general para que disminuya la probabilidad del acto parafílico.', 'Empatizar con las víctimas de su trastorno parafílico.', NULL, 'b', NULL, NULL),
  (2021, 154, NULL, '¿En qué momento del tratamiento de los trastornos disociativos se trabajará la mejora de la comunicación y el autocuidado con los pacientes con mucha fragmentación?:', 'Se iniciará ya desde la primera fase centrada en la estabilización.', 'Este trabajo con las partes nunca se iniciará en la primera fase.', 'Será necesario abordarlo en la fase tercera de integración de la personalidad, pero nunca antes.', 'Se iniciará en la fase segunda, la de integración de los recuerdos, pero nunca antes.', NULL, 'a', NULL, NULL),
  (2021, 155, NULL, 'Uno de los tratamientos que ha mostrado ser eficaz para la somatización (actual trastorno de síntomas somáticos en el DSM-5) es el de Woolfolk y Allen (2006). Este protocolo de tratamiento integra principios de la terapia cognitivo-conductual estándar con:', 'La terapia de esquemas de Young.', 'La terapia de mentalización de Bateman y Fonagy.', 'La terapia centrada en las emociones de Greenberg.', 'La entrevista motivacional de Miller y Rollnick.', NULL, 'c', NULL, NULL),
  (2021, 156, NULL, 'La terapia interpersonal:', 'Es un tratamiento de elección para la fobia social.', 'Mezcla técnicas cognitivas, psicodinámicas y gestálticas para problemas emocionales relacionados con las interacciones personales.', 'Ha demostrado un alto nivel de evidencia para los trastornos de la conducta alimentaria.', 'Ha demostrado un nivel moderado de evidencia para el tratamiento de la bulimia nerviosa y un mejor nivel de evidencia para la depresión.', NULL, 'd', NULL, NULL),
  (2021, 157, NULL, 'La terapia interpersonal y del ritmo social, es una terapia que ha mostrado su eficacia en el tratamiento de:', 'Los trastornos del sueño.', 'El trastorno bipolar.', 'La fobia social.', 'Problemas de pareja.', NULL, 'b', NULL, NULL),
  (2021, 159, NULL, 'La terapia centrada en las emociones (Greenberg y colaboradores):', 'Es un modelo terapéutico de carácter psicoanalítico que integra técnicas conductuales y cognitivas en el abordaje de los desórdenes emocionales.', 'Es un modelo terapéutico de carácter cognitivo que integra el binomio motivación-emoción en el abordaje de la depresión.', 'Es un modelo terapéutico centrado en el biofeedback como técnica principal para el equilibrio de las emociones.', 'Es un modelo terapéutico de carácter humanista experiencial que integra elementos de las prácticas centradas en el cliente y de la Gestalt.', NULL, 'd', NULL, NULL),
  (2021, 160, NULL, 'La psicoterapia centrada en la transferencia:', 'Es un tratamiento humanista con evidencia empírica para los trastornos de estrés postraumático.', 'Es un tratamiento psicodinámico con evidencia empírica para el trastorno de personalidad límite.', 'En un tratamiento que no ha obtenido evidencia empírica sobre su eficacia.', 'Es un tratamiento cognitivo con evidencia empírica para la depresión.', NULL, 'b', NULL, NULL),
  (2021, 161, NULL, 'Según la propuesta de Winter (1992) señale qué criterio debe cumplir un cliente para ser seleccionado para una terapia extraspectiva:', 'Cliente con síntomas poco centrales.', 'Cliente con baja consistencia lógica.', 'Cliente con un sistema de constructos rígidos.', 'Cliente que construye sus problemas en términos psicológicos.', NULL, 'c', NULL, NULL),
  (2021, 162, NULL, '¿Qué resulta fundamental en las terapias breves, estratégicas y centradas en soluciones?:', 'Ayudar a los pacientes de forma efectiva a cambiar la situación presente.', 'Escuchar y reconstruir el relato del problema que hace el cliente.', 'Trasmitir de forma convincente que se entiende, acepta y aprecia al cliente.', 'Llegar a un diagnóstico consensuado y libre de estigmas.', NULL, 'a', NULL, NULL),
  (2021, 163, NULL, '¿Cómo se concibe la estructura familiar desde la terapia familiar estructural?:', 'Como los vínculos de parentesco establecidos mediante criterios sociales y legales que determinan los derechos y deberes de cada miembro de la familia.', 'Como la información que aparece en el genograma.', 'Como un conjunto invisible de demandas y expectativas funcionales que organizan el modo en que interactúan los miembros de una familia.', 'Como el conjunto de pautas de comunicación funcionales y disfuncionales que determinan los roles y reglas en las familias multigeneracionales.', NULL, 'c', NULL, NULL),
  (2021, 164, NULL, '¿Cuál es el objetivo de integración metateórica en psicoterapia?:', 'Alcanzar la unificación de las diferentes psicoterapias mediante la articulación de una única teoría aplicable a todos los casos.', 'Contribuir al incremento del número de teorías y prácticas psicoterapéuticas disponibles para aumentar la cartera de servicios de los psicoterapeutas.', 'Limitar la síntesis teórica y técnica a aquellos enfoques que sean epistemológicamente compatibles.', 'Detener la proliferación de formas de conceptualización estériles en psicoterapia y guiarse por el lema de “más resultados y menos teorías”.', NULL, 'c', NULL, NULL),
  (2021, 165, NULL, 'La terapia cognitiva de la depresión de Beck se concibe como un enfoque psicoeducativo donde el diálogo entre terapeuta y cliente es esencial para el desarrollo de la terapia. Este diálogo puede ser entendido como una interacción verbal y, por tanto, analizado funcionalmente, identificando los tipos de operantes verbales que Skinner clasificó en función de los estímulos antecedentes, respuestas y reforzadores, entre otras, el tacto. ¿Cómo se define el tacto?:', 'Operante verbal que está bajo el control de un estímulo discriminativo no verbal, mantenida por reforzamiento social generalizado.', 'Operante verbal compuesta de una respuesta vocal que guarda similitud morfológica con el estímulo discriminativo verbal.', 'Operante verbal bajo el control de otros estímulos discriminativos verbales, mantenida por reforzadores negativos.', 'Operante verbal bajo el control de antecedentes verbales que no guardan similitud morfológica con la propia operante.', NULL, 'a', NULL, NULL),
  (2021, 166, NULL, 'Estudios recientes desde el análisis de la conducta han destacado el papel que juega la conducta gobernada por reglas en el desarrollo de problemas de depresión. ¿Qué sugieren los estudios realizados sobre conducta gobernada por reglas?:', 'La insensibilidad a las contingencias ambientales es una capacidad innata.', 'La conducta adquirida mediante instrucciones directas tiende a ser menos sensible a las contingencias ambientales.', 'La conducta gobernada por reglas solo puede contactar con fuentes de reforzamiento similares a las de la conducta moldeada por contingencias.', 'El seguimiento de reglas es una respuesta operante totalmente ajena a las contingencias.', NULL, 'b', NULL, NULL),
  (2021, 167, NULL, 'En el análisis funcional aplicado a un trastorno del estado de ánimo, ¿qué diferencia hay entre los estímulos condicionados (EC) y los estímulos discriminativos (Ed) en cuanto a su relación con la respuesta a la que preceden?:', 'El EC elicita la respuesta y el Ed señala la relación de contingencia entre la respuesta y el reforzador.', 'El EC causa respuestas emocionales y el Ed causa respuestas motoras.', 'El EC establece una relación de contingencia con la RC y el Ed establece una relación de contingencia con el estímulo consecuente.', 'El EC genera respuestas automáticas y el Ed genera respuestas voluntarias.', NULL, 'a', NULL, NULL),
  (2021, 168, NULL, 'Entre las principales recomendaciones clínicas internacionales ante los trastornos disociativos estaría una planificación en fases del proceso de tratamiento. La tercera fase de integración y rehabilitación:', 'Se centrará en confrontar, trabajar e integrar memorias traumáticas.', 'Se abordará la reintegración de la personalidad.', 'Se centrará en la funcionalidad interpersonal y social junto con la experimentación y verbalización de emociones fuertes.', 'Se centrará en la regulación emocional y el funcionamiento interpersonal.', NULL, 'b', NULL, NULL),
  (2021, 169, NULL, 'En el abordaje terapéutico de la psicosis, ¿cuándo decimos que se produce una adecuada metacomunicación?:', 'Cuando el paciente comunica sus propios procesos de pensamiento, de atención, memoria y, especialmente, sus procesos de lenguaje o habla.', 'Cuando se facilita que el paciente refiera las propias dificultades en la relación terapéutica.', 'Cuando el paciente identifica los estados mentales de las personas conocidas de su entorno.', 'Cuando el paciente identifica los estados mentales de las personas desconocidas de su entorno.', NULL, 'b', NULL, NULL),
  (2021, 170, NULL, '¿Cuál de estos tipos de tratamiento farmacológico NO está indicado en los trastornos bipolares?:', 'Estabilizadores del humor.', 'Antipsicóticos atípicos.', 'Antiepilépticos.', 'Venlafaxina.', NULL, 'd', NULL, NULL),
  (2021, 171, NULL, 'Respecto de la terapia cognitiva de Beck para el tratamiento de la depresión grave, señale la opción correcta:', 'Se implementa en unas 15-25 sesiones.', 'El rango de edad para su aplicación se circunscribe a 15-65 años.', 'Debe comenzarse después del periodo agudo.', 'Debe adoptar un estilo no directivo y de aceptación incondicional.', NULL, 'a', NULL, NULL),
  (2021, 172, NULL, '¿Cuál de las siguientes técnicas NO forma parte de la terapia de activación conductual para la depresión?:', 'Atención a la experiencia.', 'Extinción de evitaciones.', 'Mejora de rutinas y ritmos sociales.', 'Entrenamiento en habilidades específicas para obtener refuerzos.', NULL, 'c', NULL, NULL),
  (2021, 173, NULL, 'Las personas con diagnóstico de esquizofrenia que presentan desorganización social, recaídas frecuentes, alto número de ingresos hospitalarios, escasa asistencia a los servicios de salud mental y frecuentes visitas a urgencias, deberían ser tratados preferentemente mediante:', 'Tratamiento asertivo comunitario.', 'Tratamientos integrados multimodales.', 'Entrenamiento asertivo y habilidades sociales.', 'Tratamiento cognitivo-conductual para las recaídas.', NULL, 'a', NULL, NULL),
  (2021, 174, NULL, '¿Qué tratamiento psicológico que se utiliza en la esquizofrenia tiene como uno de sus objetivos fundamentales el trabajo con el sistema de regulación emocional denominado “amenaza y autoprotección”?:', 'Terapia cognitivo conductual para la psicosis.', 'Terapia de aceptación y compromiso para la psicosis perturbadora.', 'Terapia centrada en la compasión para la psicosis.', 'Terapia cognitiva para la psicosis perturbadora.', NULL, 'c', NULL, NULL),
  (2021, 175, NULL, 'Señale cuál de los siguientes procesos se utiliza para conseguir fomentar la llamada “mentalización” en la terapia basada en la mentalización de Bateman y Fonagy (2004) que ha demostrado ser eficaz en los trastornos de personalidad:', 'Reactivación de las relaciones de objeto.', 'Activación de los esquemas de apego.', 'Análisis de los sentimientos de vacío.', 'Aumento de la aceptación y tolerancia al malestar.', NULL, 'b', NULL, NULL),
  (2021, 176, NULL, '¿Cuál de las siguientes habilidades NO es uno de los objetivos fundamentales de la terapia dialéctica conductual (Linehan, 1993) para los trastornos de personalidad límite?:', 'Eficacia interpersonal.', 'Regulación emocional.', 'Resistencia al cambio.', 'Tolerancia al malestar.', NULL, 'c', NULL, NULL),
  (2021, 177, NULL, 'Señale cuál de los siguientes tratamientos para el trastorno de ansiedad por enfermedad/hipocondría tiene como meta aprender acerca de la naturaleza, percepción e informe de síntomas físicos y acerca de los factores psicológicos que amplifican el malestar somático:', 'Terapia cognitivo-conductual de Starcevic para la hipocondría.', 'La terapia cognitivo-educativa de Barsky.', 'Tratamiento psicoeducativo de Kellner para la hipocondría.', 'La terapia cognitivo-conductual de Warwick y Salkovskis.', NULL, 'b', NULL, NULL),
  (2021, 178, NULL, '¿En qué trastorno de personalidad se utilizan las técnicas de modificación del pensamiento dicotómico, manejo del tiempo y solución de problemas mediante la terapia cognitivo-conductual?:', 'Esquizotípico.', 'Dependiente.', 'Obsesivo-compulsivo.', 'Esquizoide.', NULL, 'c', NULL, NULL),
  (2021, 179, NULL, 'Señale la afirmación FALSA con respecto a la terapia interpersonal para la depresión:', 'Propone 4 áreas de intervención interpersonal: duelo, transiciones de rol, déficits interpersonales y disputas de rol.', 'Cuenta con un nivel de evidencia equivalente al de la terapia cognitivo-comportamental.', 'Propone 4 áreas de intervención: los eventos vitales, los síntomas, la evitación y los problemas interpersonales.', 'Se incluyen técnicas de solución de problemas.', NULL, 'c', NULL, NULL),
  (2021, 180, NULL, 'Señale la opción correcta respecto a la intervención digital en psicosis:', 'La terapia cognitiva basada en la persona para la psicosis perturbadora (PBCT) es una de las terapias que utiliza las tecnologías de la información y comunicación en su desarrollo.', 'Se ha aplicado en el ámbito de la intervención familiar, con intervenciones psicoeducativas online y foros entre cuidadores con resultados prometedores tanto en viabilidad como en utilidad.', 'Aparece con un grado de recomendación C en la guía NICE.', 'Consiste en procedimientos de monitorización digital de los síntomas con el objetivo principal de informar a los terapeutas del estado del paciente.', NULL, 'b', NULL, NULL),
  (2021, 181, NULL, 'Respecto del tratamiento para la psicosis, señale la opción FALSA:', 'En individuos con estados mentales de alto riesgo, la intervención psicológica integrada y la terapia cognitivo-conductual aparecen como las más eficaces para la prevención de la psicosis.', 'En individuos con estados mentales de alto riesgo no se puede hacer una recomendación sólida respecto a qué intervención específica (p. ej., psicológica, psicofarmacológica, dietética, basadas en las necesidades) es más efectiva para la prevención de la psicosis.', 'Los tratamientos psicológicos con carácter preventivo todavía no aparecen en las principales guías de tratamiento para la psicosis.', 'Los modelos de prevención se pueden aplicar tanto en individuos con estados mentales de alto riesgo como en los primeros episodios psicóticos.', NULL, 'c', NULL, NULL),
  (2021, 182, NULL, '¿Cuál de las siguientes afirmaciones NO es cierta en relación a la intervención familiar en la psicosis?:', 'Está fundamentalmente indicada para familias de sujetos con esquizofrenia de larga evolución que presentan una elevada emoción expresada.', 'Es una de las intervenciones psicosociales más ampliamente validada empíricamente en los trastornos psicóticos.', 'Las intervenciones familiares son consideras como un indicador de calidad asistencial en la guía NICE.', 'Puede ser de administración individual (unifamiliar), grupal (multifamiliar) o combinada.', NULL, 'a', NULL, NULL),
  (2021, 183, NULL, 'La ausencia de protodeclarativos (señalar con el dedo para compartir un interés) con 18 meses es una señal de alerta de:', 'Trastorno del lenguaje.', 'No es un indicador de patología porque no aparecen hasta los dos años.', 'Trastorno del espectro autista.', 'Discapacidad intelectual.', NULL, 'c', NULL, NULL),
  (2021, 184, NULL, '¿Cuál de los siguientes tratamientos o programas para el tratamiento psicológico en población infantojuvenil NO sigue un enfoque de tratamiento transdiagnóstico?:', 'Super Skills for Life (SSL).', 'Protocolo unificado para adolescentes (UPA).', 'The Incredible Years (IY).', 'Terapia multisistémica (MST).', NULL, 'c', NULL, NULL),
  (2021, 185, NULL, '¿Para qué trastorno está recomendado el programa multicomponente de escenificaciones emotivas?:', 'Trastorno de pánico.', 'Ansiedad social.', 'Trastorno obsesivo-compulsivo.', 'Fobias específicas.', NULL, 'd', NULL, NULL),
  (2021, 186, NULL, 'En relación al protocolo unificado (PU) para el tratamiento transdiagnóstico de los trastornos emocionales de Barlow y colaboradores (2018), señale la opción FALSA:', 'Uno de los objetivos es prevenir la evitación emocional.', 'No ha sido adaptado a población infantil pero sí a adolescentes.', 'Intenta aumentar la conciencia sobre las emociones.', 'Se utiliza tanto para intervenir en el ámbito de los trastornos emocionales como a nivel preventivo.', NULL, 'b', NULL, NULL),
  (2021, 187, NULL, 'Con respecto a la terapia de interacción padres-hijos (Parent-Child Interaction Therapy, PCIT), señale la opción FALSA:', 'Es un tratamiento basado en la evidencia para menores de edad con problemas de comportamiento disruptivo.', 'Se considera un tratamiento basado en la terapia de conducta.', 'Incluye estrategias de atención contingente positiva y estrategias de disciplina efectivas.', 'Es un tratamiento basado en la evidencia para menores de edad con trastornos de la conducta alimentaria.', NULL, 'd', NULL, NULL),
  (2021, 188, NULL, '¿Cuál de los siguientes tratamientos NO forma parte de los tratamientos bien establecidos o probablemente eficaces para los trastornos de la conducta alimentaria?:', 'Terapia cognitivo-conductual individual.', 'Terapia de aceptación y compromiso.', 'Terapia familiar-conductual.', 'Terapia familiar sistémica.', NULL, 'b', NULL, NULL),
  (2021, 189, NULL, '¿Qué tratamiento se considera bien establecido para la enuresis nocturna?:', 'El entrenamiento en retención.', 'El método de alarma.', 'El entrenamiento en cama seca.', 'La imipramina.', NULL, 'b', NULL, NULL),
  (2021, 190, NULL, 'El trauma en la infancia puede manifestarse de manera muy distinta en función de la edad o del sexo. ¿Para cuál de las siguientes afirmaciones existe evidencia?:', 'En general, los niños tienen más facilidad para expresar sus emociones que las niñas, predominando en los niños los síntomas ansiosos, mientras que en las niñas son más frecuentes las reacciones depresivas.', 'Tanto en los niños como en las niñas puede surgir la inadaptación escolar y las dificultades de socialización, tendiendo, más a menudo que los adultos, a culparse a sí mismos directa o indirectamente del suceso traumático.', 'En las niñas son más frecuentes los trastornos de conducta, y en los niños los trastornos depresivos, las conductas temerarias y la irritabilidad.', 'Los niños más mayores y prepúberes suelen expresar los síntomas de reexperimentación del suceso traumático directa o simbólicamente mediante juegos relacionados con el trauma de naturaleza repetitiva, ansiosa y rígida.', NULL, 'b', NULL, NULL),
  (2021, 191, NULL, '¿Cuál de las siguientes razones justifican las dificultades en la identificación del trastorno de ansiedad generalizada (TAG) en la infancia?:', 'La forma infantil del TAG suele identificarse como temperamento ansioso o como un perfil de madurez precoz, siendo considerados niños excesivamente escrupulosos, responsables y perfeccionistas, algo que puede enmascarar el trastorno por tratarse de cualidades que agradan a los adultos.', 'Para el diagnóstico del TAG, según criterios del DSM-5, sólo se requieren dos de los seis síntomas posibles, y ello hace que haya un sobrediagnóstico del trastorno.', 'La preocupación ansiosa, aspecto nuclear del TAG, es un proceso cognitivo que se desarrolla siempre antes de los 8 años, y por ello, el niño no puede expresarla con claridad.', 'En los niños con TAG las inquietudes y preocupaciones a menudo se refieren al pasado, a su salud y al bienestar de su familia, incrementándose el miedo a separarse de sus figuras de apego.', NULL, 'a', NULL, NULL),
  (2021, 192, NULL, 'En lo que respecta al diagnóstico diferencial del trastorno del espectro autista (TEA) con otros trastornos, es cierto que:', 'La presencia de patrones conductuales restrictivos y repetitivos está presente en el comportamiento de las personas con TEA y de las personas con trastorno de la comunicación social (pragmática).', 'Las rabietas en personas con TEA y en personas con trastorno por déficit de atención/hiperactividad (TDAH) difieren en el estímulo antecedente, estando más asociadas a cambios inesperados en el caso de TEA y a la impulsividad y bajo control en el caso del TDAH.', 'El mutismo en personas con TEA y en personas con mutismo selectivo está ocasionado por diferentes estímulos antecedentes, estando asociado a la evitación de situaciones de ansiedad en el caso del TEA y a la evitación social en el caso del mutismo selectivo.', 'Las personas con trastorno obsesivo-compulsivo (TOC) y las personas con TEA realizan rituales asociados a conductas evitativas que suelen ir acompañados de una sensación de agrado.', NULL, 'b', NULL, NULL),
  (2021, 193, NULL, 'Uno de los tratamientos psicológicos para intervenir en las secuelas del abuso sexual infantil es la terapia cognitivo-conductual focalizada en el trauma. ¿Cuál de las siguientes NO sería una fase de esta terapia?:', 'Debriefing.', 'Estabilización y desarrollo de habilidades.', 'Reelaboración del trauma.', 'Consolidación y cierre.', NULL, 'a', NULL, NULL),
  (2021, 194, NULL, '¿Cuál de las siguientes afirmaciones es FALSA en relación al tratamiento psicológico mejor establecido para las conductas autolíticas y la ideación suicida en adolescentes en la terapia dialéctico-conductual para adolescentes?:', 'Pretende reducir las conductas autolíticas a través de la adquisición de nuevas habilidades de regulación emocional, tolerancia a la frustración y la construcción de una vida que merezca la pena ser vivida.', 'Incluye apoyo telefónico.', 'Se realizan sesiones semanales de terapia individual con el adolescente, con familiares y grupales.', 'Trabaja la reestructuración de los pensamientos negativos asociados a las autolesiones.', NULL, 'd', NULL, NULL),
  (2021, 195, NULL, '¿Cuál de las siguientes NO es una fase de la Imagery Rehearsal Therapy (IRT) (terapia de ensayo o repaso en imaginación) para las pesadillas?:', 'El niño o niña completa el diario de intervención.', 'Con los ojos cerrados y relajado, ensaya y visualiza mentalmente una versión modificada de la pesadilla.', 'El niño o niña recuerda la pesadilla de la noche anterior y modifica su contenido del modo que desee.', 'Se trabajan, en imaginación, sesgos cognitivos y significados biográficos acerca del contenido de las pesadillas.', NULL, 'd', NULL, NULL),
  (2021, 196, NULL, 'Respecto del estrés postraumático en niños menores de seis años, señale la opción correcta:', 'No puede diagnosticarse trastorno de estrés postraumático (TEP) a esa edad.', 'Los recuerdos intrusivos pueden no ser necesariamente angustiosos y manifestarse a través del juego.', 'Se incluyen como eventos potencialmente traumáticos las escenas violentas que solamente se han visto en la televisión o en fotografías.', 'Cuando lo que predomina es la irritabilidad y los arrebatos de furia ha de diagnosticarse trastorno negativista desafiante.', NULL, 'b', NULL, NULL),
  (2021, 197, NULL, 'El programa Coping Cat es un tratamiento:', 'Altamente estructurado para la ansiedad infantil.', 'Dirigido a niños preescolares con ansiedad por separación.', 'Indicado para la depresión en adolescentes.', 'Multicomponente para la ansiedad social.', NULL, 'a', NULL, NULL),
  (2021, 198, NULL, 'En relación al concepto de setpoint, de Keesey (1980), señale la opción FALSA:', 'El cuerpo tiende a regularse para dificultar una bajada excesiva de peso.', 'El cuerpo tiende a regularse para obstaculizar un aumento rápido y extremo de peso.', 'Permite comprender en cierta medida el efecto suelo y el efecto techo de la alimentación.', 'El setpoint es inamovible.', NULL, 'd', NULL, NULL),
  (2021, 199, NULL, 'En relación a la teoría del dolor de Melzack y Wall, conocida como teoría de la puerta, señale la opción FALSA:', 'El dolor es visto como un fenómeno complejo vinculado al daño tisular, el estado emocional, los aspectos motivacionales y de reforzamiento, así como a los factores atencionales.', 'La actividad neuronal aferente de los nocioceptores periféricos está modulada en el asta dorsal de la médula, que actúa como una puerta que impide, o no, el paso de los impulsos nerviosos que proceden de los nocioceptores y del córtex.', 'La puerta puede cerrarse o abrirse por mensajes descendentes del cerebro, el llamado mecanismo de control central, de modo que las reacciones emocionales como la ansiedad, el miedo, o el estrés pueden exacerbar la sensación de dolor.', 'Ni las creencias del sujeto ni las experiencias previas afectarían la sensación de dolor.', NULL, 'd', NULL, NULL),
  (2021, 200, NULL, 'El sobrepeso y la obesidad constituyen factores de riesgo importantes para la salud que se han asociado a distintas enfermedades físicas. Señale cuál de las siguientes NO lo está o lo está en menor medida:', 'Hiperuricemia.', 'Diabetes.', 'Problemas respiratorios y cardiovasculares.', 'Hipertensión.', NULL, 'a', NULL, NULL),
  (2021, 201, NULL, 'Respecto del tratamiento del TDAH, señale la opción correcta:', 'La guía NICE (2018) recomienda el metilfenidato como tratamiento farmacológico de primera línea para niños mayores de cinco años y para adolescentes.', 'La OMS (2016) recomienda la derivación a un especialista para el tratamiento farmacológico (i.e. metilfenidato) si los tratamientos psicológicos y psicosociales han fracasado y el niño tiene más de 12 años.', 'El entrenamiento a padres y los programas escolares de manejo del comportamiento parecen resultar eficaces; si bien, el tratamiento psicosocial con involucración de los padres parece que mejora más los síntomas externalizantes que los internalizantes.', 'Si bien el metilfenidato ha mostrado eficacia, la lisdexanfetamina se ha mostrado claramente más ineficaz.', NULL, 'a', NULL, NULL),
  (2021, 202, NULL, 'Señale la afirmación correcta respecto de las consecuencias funcionales del trastorno bipolar II (DSM-5):', 'La recuperación funcional no se suele retrasar respecto de la recuperación de los síntomas del trastorno bipolar.', 'El deterioro cognitivo en el trastorno bipolar II es más leve que en el trastorno bipolar I.', 'En los test cognitivos, los pacientes con trastorno bipolar II realizan los test cognitivos peor que los individuos sanos, a excepción de los de memoria y fluidez semántica.', 'En torno a un 50%, una vez terminado un episodio entra directamente en otro sin recuperación interepisódica.', NULL, 'c', NULL, NULL),
  (2021, 203, NULL, 'Dentro de los modelos de inteligencia, ¿qué modelo postula que la inteligencia deriva de la combinación de contenidos, operaciones y productos?:', 'El modelo cúbico de estructura del intelecto de Guilford.', 'El modelo de la teoría triárquica de Sternberg.', 'El modelo jerárquico de la inteligencia de Vernon.', 'El modelo de los tres estratos de Carroll.', NULL, 'a', NULL, NULL),
  (2021, 204, NULL, 'En el modelo analítico funcional de Stephen Haynes para la formulación de un caso clínico, ¿qué representa el símbolo del rombo?:', 'Variable causa o moderador.', 'Problema efecto de otro problema.', 'Causa original no modificable.', 'Variable causal hipotética.', NULL, 'c', NULL, NULL),
  (2021, 205, NULL, '¿Cuál de las siguientes es una condición necesaria para la aplicación de un programa de manejo de contingencias mediante incentivos para el tratamiento de la adicción a drogas?:', 'Monitorizar frecuentemente la conducta objetivo, normalmente el uso de la droga principal.', 'Evaluar el patrón de consumo de todas las drogas, además de la sustancia principal.', 'Descartar la existencia de otros trastornos asociados, además de la adicción a drogas.', 'Implicar a terceras personas, preferentemente familiares, para manejar los incentivos.', NULL, 'a', NULL, NULL),
  (2021, 206, NULL, 'En los datos de observación “no reactivos” considerados como productos de conducta, se incluyen:', 'Los atributos.', 'Las interacciones.', 'La medida de erosión.', 'Las conductas.', NULL, 'c', NULL, NULL),
  (2021, 207, NULL, 'Para el trastorno de estrés postraumático en niños y adolescentes, el tratamiento con mayor apoyo empírico es:', 'La terapia cognitivo-conductual centrada en el trauma.', 'La relajación.', 'El EMDR.', 'Las técnicas de autocontrol.', NULL, 'a', NULL, NULL),
  (2021, 208, NULL, '¿Cuál de las siguientes afirmaciones es una característica del diseño de bloques aleatorios?:', 'Se asume la interacción entre la variable manipulada y la de bloqueo.', 'Permite reducir la heterogeneidad de las unidades experimentales y, por lo tanto, aumentar la potencia de la prueba F utilizada para analizar el efecto del tratamiento.', 'La variable de bloqueo no debe estar correlacionada con la variable dependiente.', 'Utiliza una estrategia de control estadístico denominada técnica de bloqueo.', NULL, 'b', NULL, NULL),
  (2021, 209, NULL, 'Según la teoría de la auto-discrepancia de Higgins, las diferencias entre el autoconcepto real y el autoconcepto responsable/del deber provocan fundamentalmente:', 'Depresión.', 'Abatimiento.', 'Ansiedad.', 'Decepción.', NULL, 'c', NULL, NULL),
  (2021, 210, NULL, 'Con respecto al área de fusión de Panum y su relación con el horópter en la percepción visual de la profundidad, ¿dónde es menor el tamaño del área de fusión de Panum?:', 'En la periferia visual.', 'En el entorno del punto de fijación.', 'En la hemirretina nasal.', 'En la hemirretina temporal.', NULL, 'b', NULL, NULL);
